/* 扫码登录：让官网自己的登录页替我们登录。
 *
 * 登录接口（login.douyin.com/passport/web/get_qrcode 等）除了 a_bogus 还要登录 SDK 自己算的
 * sign / qs / p_* 和一段服务器下发的 challenge 脚本；不带就回 4031「存在安全风险，已阻止」。
 * 这些都打包在官网主程序里，自己复现不现实。而官网的页面大多不许嵌入（主站 SPA 带
 * X-Frame-Options: DENY + frame-ancestors 白名单；sso.douyin.com/login/ 已弃用，无条件跳回
 * 主站）。**唯一能嵌入的是 www.douyin.com/login_page**（2026-09-29 模拟电视实测：没有 XFO，
 * 框里的官网代码自己调 get_qrcode 成功，二维码是一张 data: PNG）。
 *
 * 所以：隐藏框开 login_page，service 指向 robots.txt —— 扫码确认后它跳到 service，而主站
 * 页面会被拦，robots.txt 不会。我们只把框里的二维码图片搬到电视上放大，读面板文字告诉
 * 观众进展。出码、签名、轮询、种会话 cookie 全是官网自己的代码做的。
 * 框用 sandbox 挡住它改顶层页面（官网页面在框里可能想把整个 App 跳走）。
 */
var Login = (function () {
    "use strict";

    var SERVICE = "https://www.douyin.com/robots.txt";
    var URL_ = "https://www.douyin.com/login_page?service=" + encodeURIComponent(SERVICE);

    var frame = null;
    var timer = 0;
    var cb = null;
    var lastQr = "", lastText = "", lastBody = "", t0 = 0, refreshedAt = 0, done = false;
    var panel = null;          // 二维码往上四层的容器：状态提示（已扫码、已失效）出现在这里

    function stop() {
        clearInterval(timer);
        timer = 0;
        if (frame && frame.parentNode) { frame.parentNode.removeChild(frame); }
        frame = null;
    }

    function tick() {
        var d, href;
        try { d = frame.contentDocument; href = frame.contentWindow.location.href; } catch (e) {
            cb({phase: "error", msg: "登录页不可访问（" + e.name + "）"});
            stop();
            return;
        }
        if (!d) { return; }
        /* 确认之后官网把框跳到 service。到了 robots.txt 就说明会话 cookie 已经种下了。 */
        if (href.indexOf("/robots.txt") >= 0) {
            if (!done) {
                done = true;
                Log.report("login", "框落到 robots.txt，用时 " + Math.round((Date.now() - t0) / 1000) + " 秒");
                stop();
                cb({phase: "done"});
            }
            return;
        }
        if (href.indexOf("chrome-error") === 0 || href === "about:blank" && Date.now() - t0 > 15000) {
            Log.report("login", "登录页落到 " + href.slice(0, 40) + "，重开");
            open();
            return;
        }
        var imgs = d.querySelectorAll("img[src^=\"data:image\"]");
        var qr = null;
        for (var i = 0; i < imgs.length; i++) {
            var r = imgs[i].getBoundingClientRect();
            if (r.width >= 100 && Math.abs(r.width - r.height) < 10) { qr = imgs[i]; }
        }
        if (qr && qr.src !== lastQr) {
            lastQr = qr.src;
            Log.report("login", "二维码到了（" + Math.round((Date.now() - t0) / 1000) + " 秒）");
            cb({phase: "qr", src: qr.src});
        }
        if (qr) { panel = qr; for (var k = 0; k < 4 && panel.parentElement; k++) { panel = panel.parentElement; } }
        /* 整页正文只记日志 —— 里面本来就有「验证码登录」「获取验证码」，拿它匹配「验证」会误报。 */
        var body = d.body ? d.body.innerText.replace(/\s+/g, " ") : "";
        if (body !== lastBody) {
            lastBody = body;
            Log.report("login", "整页文字：" + Diag.priv(body.slice(0, 140)));   // 扫码之后这页上可能有昵称
            /* 新设备验证这类我们处理不了的，原样给观众看，让他们在手机上照做。 */
            if (/身份验证|安全验证|验证身份/.test(body)) { cb({phase: "status", msg: body.slice(0, 60)}); }
        }
        var text = panel && panel.isConnected !== false ? panel.innerText.replace(/\s+/g, " ") : "";
        if (text !== lastText) {
            lastText = text;
            var msg = "";
            if (/失效|过期|刷新/.test(text)) {
                msg = "二维码过期了，正在换一张…";
                clickRefresh(d);
            } else if (/扫码成功|已扫码|确认/.test(text)) {
                msg = "已扫码，请在手机上点「确认登录」";
            }
            if (msg) { cb({phase: "status", msg: msg}); }
        }
    }

    /* 过期时点框里的「刷新」。找不到就整个重开 —— 但 20 秒内只重开一次，免得循环。 */
    function clickRefresh(d) {
        if (Date.now() - refreshedAt < 20000) { return; }
        refreshedAt = Date.now();
        var all = d.querySelectorAll("*");
        for (var i = all.length - 1; i >= 0; i--) {
            var el = all[i];
            if (el.children.length === 0 && /刷新/.test(el.textContent || "")) {
                try { el.click(); Log.report("login", "点了框里的「刷新」"); return; } catch (e) {}
            }
        }
        Log.report("login", "框里找不到「刷新」，重开登录页");
        open();
    }

    function open() {
        stop();
        lastQr = ""; lastText = ""; lastBody = ""; panel = null; done = false;
        t0 = Date.now();
        frame = document.createElement("iframe");
        frame.className = "login-frame";
        frame.setAttribute("sandbox", "allow-scripts allow-same-origin allow-forms allow-popups");
        frame.src = URL_;
        document.body.appendChild(frame);
        timer = setInterval(tick, 800);
    }

    return {
        /* onState({phase: "qr", src} | {phase: "status", msg} | {phase: "done"} | {phase: "error", msg}) */
        start: function (onState) { cb = onState; open(); },
        stop: stop,
        active: function () { return !!frame; }
    };
})();

files.js/grid.js:
/* 网格页：上面是头部（头像、名字、一行数字、一段说明），下面是 3:4 竖卡片的网格，遥控器上下左右选，确认键从这一条开始放
 * （放着的时候上下键在这一页的视频里刷）。四种页共用这一套（2026-10-18 从作者主页抽出来）：
 *   作者主页  暂停时选中作者、确认键进来（2026-09-30 用户要求）
 *   「我」    顶上一排：观看历史 · 喜欢 · 收藏 · 诊断日志 · 上传诊断日志 · 退出登录，前三排各一个网格（2026-10-18）
 *   合集      暂停时选中「合集」、确认键进来：选集，焦点落在正在看的那一集（2026-10-18）
 *   精选      标签自己就是这一页，没有头部；16:9 三列宽卡片，照 bilibili-tizen 的首页（2026-10-22 用户要求：精选不上下滑，像手机上一样挑着看）
 * 页和页之间怎么走（一摞页，返回键一层层退）在 app.js，这里只管一页画什么、焦点在哪。
 *
 * 作者资料接口 2026-09-30 在全新匿名测试台（spike/desktop-harness，MODE=author）里问过：
 *   GET /aweme/v1/web/user/profile/other/  sec_user_id → user.{nickname, signature, following_count, follower_count,
 *       total_favorited, aweme_count, avatar_300x300}，匿名 status_code=0。
 * 各种列表的接口见 feed.js。
 */
var Grid = (function () {
    "use strict";

    /* 4 列（用户 09-30 看了 6 列嫌小）、3:4 竖卡片（用户要和抖音官方一致；接口给的封面第一个地址就是官方裁好的
     * 3:4 小图 cropcenter:323:430）。一屏只放得下一整行，所以焦点行钉在 ANCHOR：上面露一截上一行、下面露大半行下一行，
     * 上下键每次正好滚一行。网格从哪一行开始（top）每种页不一样：「我」上面还有一排。 */
    var TALL = {cols: 4, cw: 398, ch: 531, gap: 36, left: 110, anchor: 120, wide: false};
    /* 精选：三列 576 宽、间距 32、左右各 64，正好铺满 1920（bilibili-tizen 首页的尺寸，它在 65 寸上从沙发看量过：四列时标题糊成一片）。
     * 卡片里 16:9 的图 556×313，下面两行标题、一行灰字（@作者 · 赞 · 多久以前），时长贴在图的右下角。一屏放得下两行。 */
    var WIDE = {cols: 3, cw: 576, ch: 463, gap: 32, left: 64, anchor: 120, wide: true};
    function row(g) { return g.ch + g.gap; }
    /* 翻动时的帧（2026-09-30 用户说往下滚「有点卡顿」）：按键后 450ms 里 rAF 的间隔。合成层临时提起 / 放下、新露出来的
     * 部分要光栅化时，主线程的帧会被顶住，长间隔就是看得见的卡。自测 --grid 在同一轮里轮换 MODES，电视上各滚 24 次：
     *   旧     最长帧间隔中位 167ms，掉帧 264，长任务 3872ms —— 250ms 的滚动里卡住六分之一秒
     *   层     33ms，掉帧 37，长任务 341ms（整块网格 will-change: transform，常驻一个合成层）
     *   层+瞬  33ms，掉帧 22，长任务 0（再加焦点卡片放大不做过渡）—— 默认 */
    var MODES = {"旧": ["", ""], "层": ["layer", ""], "层+瞬": ["layer", "snap"]};
    var mode = "层+瞬";
    var probes = [], told = 0, longMs = 0;
    try {
        new PerformanceObserver(function (l) {
            var es = l.getEntries();
            for (var i = 0; i < es.length; i++) { longMs += es[i].duration; }
        }).observe({entryTypes: ["longtask"]});
    } catch (e) {}
    var $ = function (id) { return document.getElementById(id); };
    var cur = null;           // 正显示的那一页

    function count(n) {
        if (n >= 100000000) { return (n / 100000000).toFixed(1) + "亿"; }
        if (n >= 10000) { return (n / 10000).toFixed(1) + "万"; }
        return String(n || 0);
    }
    function first(list) { return list && list.url_list && list.url_list[0] || ""; }
    function clock(ms) {
        var s = Math.round(ms / 1000), h = Math.floor(s / 3600), m = Math.floor(s / 60) % 60, x = s % 60;
        return (h ? h + ":" + (m < 10 ? "0" : "") : "") + m + ":" + (x < 10 ? "0" : "") + x;
    }
    function ago(sec) {
        if (!sec) { return ""; }
        var d = (Date.now() / 1000 - sec) / 86400;
        if (d < 1 / 24) { return "刚刚"; }
        if (d < 1) { return Math.floor(d * 24) + " 小时前"; }
        if (d < 30) { return Math.floor(d) + " 天前"; }
        var t = new Date(sec * 1000);
        return (t.getFullYear() === new Date().getFullYear() ? "" : t.getFullYear() + "-") + (t.getMonth() + 1) + "-" + t.getDate();
    }
    function cardClass(p, on) { return (p.geo.wide ? "card wide" : "card") + (on ? " on" : ""); }

    /* 一页。tabs 只有「我」有：顶上一排，焦点在那一排时 zone 是 "tabs"。每一排各一个视频流（feeds[key]，第一次切过去才建）。
     *   playName / backName：放这一页的视频时顶上那行写什么（「@谁 的作品 · 返回键回到 TA 的主页」）
     *   label(it)：卡片左下角那行（默认点赞数；合集写第几集）
     *   tabName(t)：顶上那一排这一项现在写什么（默认 t.name；「诊断日志：开 / 关」跟着开关变）
     *   want：打开时焦点要落在哪一条（合集：正在看的那一集），没取到就接着往后取 */
    function make(kind, o) {
        return {kind: kind, title: o.title || "", avatar: o.avatar || "", stats: o.stats || "", sign: o.sign || "",
                geo: o.geo || TALL, top: o.top || (o.tabs ? 380 : 300), tabs: o.tabs || null, tab: 0, zone: o.tabs ? "tabs" : "grid", feeds: {},
                makeFeed: o.makeFeed, label: o.label || null, empty: o.empty || null, foot: o.foot || null, tabName: o.tabName || null,
                playName: o.playName || "", backName: o.backName || "", want: o.want || "", wantTries: 0,
                sel: 0, on: -1, offset: 0, cards: [], loading: false, err: ""};
    }
    function key(p) { return p.tabs ? p.tabs[p.tab].key : "main"; }
    function feedOf(p) {
        var k = key(p);
        if (!p.feeds[k] && p.makeFeed) { p.feeds[k] = p.makeFeed(k) || null; }
        return p.feeds[k] || null;
    }

    function avatar(src) {
        var av = $("gp-avatar");
        av.style.visibility = "hidden";
        if (!src) { return; }
        av.onload = function () { av.style.visibility = "visible"; };
        av.src = src;
    }

    /* 头部有新消息了（资料接口回来了）：记在页上，正显示的话顺手画上。 */
    function header(p, o) {
        for (var k in o) { if (o.hasOwnProperty(k) && o[k] !== undefined) { p[k] = o[k]; } }
        if (cur !== p) { return; }
        $("gp-name").textContent = p.title;
        $("gp-stats").textContent = p.stats;
        $("gp-sign").textContent = p.sign;
        if (o.avatar) { avatar(p.avatar); }
    }

    /* 顶上那一排（「我」的四项、选集的分组）。分组多了一行放不下：横着挪，让亮着的那一项露出来。 */
    function drawTabs() {
        var p = cur, html = "";
        if (!p.tabs) { $("gp-tabs").innerHTML = ""; return; }
        for (var i = 0; i < p.tabs.length; i++) {
            html += "<span class=\"t" + (i === p.tab ? " on" : "") + (i === p.tab && p.zone === "tabs" ? " focus" : "") + "\">" + (p.tabName ? p.tabName(p.tabs[i]) : p.tabs[i].name) + "</span>";
        }
        $("gp-tabs").innerHTML = "<div class=\"in\">" + html + "</div>";
        var inner = $("gp-tabs").firstChild, on = inner.childNodes[p.tab];
        var x = Math.max(0, Math.min(on.offsetLeft - 300, inner.scrollWidth - $("gp-tabs").offsetWidth));
        inner.style.transform = "translateX(" + (-x) + "px)";
    }
    /* 选集的一组最多画 limit 张（流本身会接着往后取，那是给接着放下一集用的）。 */
    function limit(p) { return p.tabs && p.tabs[p.tab].limit || 0; }
    function shown(p, f) {
        var list = f ? f.all() : [], lim = limit(p);
        return lim && list.length > lim ? list.slice(0, lim) : list;
    }

    /* 整页重画：新开一页、从放着的视频回来、换一排。卡片全部重建（图在浏览器缓存里）。 */
    function render(p) {
        cur = p;
        $("grid-page").className = "show " + p.kind;
        $("gp-name").textContent = p.title;
        $("gp-stats").textContent = p.stats;
        $("gp-sign").textContent = p.sign;
        avatar(p.avatar);
        $("gp-grid").innerHTML = "";
        $("gp-scroll").className = MODES[mode][0];
        $("gp-grid").className = MODES[mode][1];
        p.cards = [];
        p.on = -1;
        p.offset = -1;
        draw();
        var f = feedOf(p);
        if (f && !f.all().length) { more(); }
    }

    function more() {
        var me = cur;
        var f = me && feedOf(me);
        if (!f || me.loading || !f.hasMore() || limit(me) && f.all().length >= limit(me)) { return; }
        me.loading = true;
        me.err = "";
        draw();
        var t0 = Date.now();
        var k = key(me);
        f.loadMore().then(function (added) {
            me.loading = false;
            if (cur !== me || key(me) !== k) { return; }
            if (!me.cards.length) { Log.report("网格", me.kind + (me.tabs ? "·" + k : "") + " 第一页 " + (Date.now() - t0) + "ms，" + added + " 条"); }
            draw();
        }, function (e) {
            me.loading = false;
            if (cur !== me || key(me) !== k) { return; }
            me.err = e.message;
            Log.report("网格", me.kind + (me.tabs ? "·" + k : "") + " 列表取不到（" + (Date.now() - t0) + "ms）：" + e.message);
            Diag.incident(({author: "作者主页", me: "「我」", mix: "选集", jingxuan: "精选"}[me.kind] || me.kind) + (me.tabs ? "·" + me.tabs[me.tab].name : "") + "列表加载失败：" + e.message);
            draw();
        });
    }

    /* 把还没画的条目补成卡片（放这一页的视频时往下刷也会取新页），再写底下那行字。 */
    function draw() {
        var me = cur;
        var f = feedOf(me);
        var list = shown(me, f);
        var full = limit(me) && list.length >= limit(me);
        var grid = $("gp-grid"), g = me.geo;
        for (var i = me.cards.length; i < list.length; i++) {
            var it = list[i];
            var c = document.createElement("div");
            c.className = cardClass(me, false);
            c.style.left = (g.left + (i % g.cols) * (g.cw + g.gap)) + "px";
            c.style.top = (me.top + Math.floor(i / g.cols) * row(g)) + "px";
            if (g.wide) {
                /* 宽卡片用作者做的封面（大字都在上面）：横版 16:9 的（card）优先，没有就用 thumb（作者封面；精选接口给的是 4:3，裁掉上下一点），
                 * 再没有才用 cover（视频里抽的一帧，没有字 —— 第一版就是用的它，用户问「手机上封面都有大字，你的怎么没有」）。 */
                c.innerHTML = "<div class=\"th\"><img><span class=\"dur\"></span></div><div class=\"tt\"></div><div class=\"by\"></div>";
                c.firstChild.firstChild.src = it.card || it.thumb || it.cover;
                c.firstChild.lastChild.textContent = it.dur ? clock(it.dur) : "";
                c.childNodes[1].textContent = it.desc;
                c.childNodes[2].textContent = [it.author ? "@" + it.author : "", "♥ " + count(it.likes), ago(it.time)].filter(function (x) { return x; }).join(" · ");
            } else {
                c.innerHTML = "<img><div class=\"shade\"></div><div class=\"d\"></div><div class=\"l\"></div>" + (it.top && me.kind === "author" ? "<div class=\"pin\">置顶</div>" : "");
                c.firstChild.src = it.thumb || it.cover;
                c.childNodes[2].textContent = it.desc;
                c.childNodes[3].textContent = me.label ? me.label(it) : "♥ " + count(it.likes);
            }
            grid.appendChild(c);
            me.cards.push(c);
        }
        /* 合集：焦点要落在正在看的那一集上。一页 12 集，没取到就接着取（最多 15 页）。 */
        if (me.want) {
            for (var w = 0; w < list.length; w++) { if (list[w].id === me.want) { break; } }
            if (w < list.length) { me.sel = w; me.zone = "grid"; me.want = ""; }
            else if (f && f.hasMore() && !full && !me.loading && !me.err && me.wantTries++ < 15) { setTimeout(more, 0); }
            else if (!me.loading) { me.want = ""; }
        }
        var n = list.length;
        var msg = "";
        if (!f) { msg = me.empty ? me.empty(key(me), null) : ""; }
        else if (me.loading) { msg = "正在加载…"; }
        else if (me.err) { msg = (n ? "后面的加载失败（" + me.err + "），往下翻重试" : "加载失败（" + me.err + "），按确认键重试"); }
        else if (full && me.tab < me.tabs.length - 1) { msg = "后面的集在顶上那一排的「" + me.tabs[me.tab + 1].name + "」"; }
        else if (!f.hasMore()) {
            if (!n) { msg = me.empty ? me.empty(key(me), f) : "这里是空的"; }
            else { msg = me.foot ? me.foot(f, n) : "没有更多了"; }
        }
        var ft = $("gp-foot");
        ft.textContent = msg;
        ft.style.top = (n ? me.top + Math.ceil(n / g.cols) * row(g) + 10 : me.top + 120) + "px";
        focus(false);
    }

    function scroll(off) {
        if (!cur || off === cur.offset) { return false; }
        cur.offset = off;
        $("gp-scroll").style.transform = "translateY(" + (-off) + "px)";
        return true;
    }

    /* 焦点行钉在 ANCHOR（第一行时连头部一起露出来）。快翻到底了就取下一页 —— 只在观众往下走时取，画完一页不自己
     * 接着取（一页全是图文、有 has_more 的作者会一直问下去）。回这次滚没滚。焦点在「我」顶上那一排时没有卡片亮着。 */
    function focus(moved) {
        var me = cur;
        drawTabs();
        var n = me.cards.length;
        var on = me.zone === "grid" && n ? Math.min(me.sel, n - 1) : -1;
        if (on >= 0) { me.sel = on; }
        if (me.on !== on) {
            if (me.cards[me.on]) { me.cards[me.on].className = cardClass(me, false); }
            if (on >= 0) { me.cards[on].className = cardClass(me, true); }
            me.on = on;
        }
        if (on < 0) { return scroll(0); }
        var g = me.geo, R = row(g);
        var r = Math.floor(on / g.cols), rows = Math.ceil(n / g.cols);
        /* 滚到底就不再往上推：最后一行和底下那行字贴着屏幕下沿，不留一大块空。 */
        var off = r === 0 ? 0 : Math.min(me.top + r * R - g.anchor, Math.max(0, me.top + rows * R + 70 - 1080));
        var scrolled = scroll(off);
        if (moved && r >= rows - 2) { more(); }
        return scrolled;
    }

    function measure(scrolled) {
        var p = {mode: mode, scrolled: scrolled, frames: 0, maxGap: 0, drops: 0, first: -1, long: longMs};
        var t0 = performance.now(), last = t0;
        function tick(now) {
            var gap = now - last;
            if (!p.frames) { p.first = Math.round(performance.now() - t0); }     // now 是这一帧的起点，可能早于按键
            else {
                if (gap > p.maxGap) { p.maxGap = gap; }
                if (gap > 25) { p.drops += Math.round(gap / 16.7) - 1; }
            }
            p.frames++;
            last = now;
            if (now - t0 < 450) { requestAnimationFrame(tick); return; }
            p.maxGap = Math.round(p.maxGap);
            p.long = Math.round(longMs - p.long);
            probes.push(p);
            if (probes.length > 300) { probes.shift(); }
            /* 平时每滚 10 次报一行，看真实使用时卡不卡。 */
            var sc = probes.filter(function (q) { return q.scrolled; });
            if (sc.length - told >= 10) {
                var g = sc.slice(told);
                told = sc.length;
                var gaps = g.map(function (q) { return q.maxGap; }).sort(function (a, b) { return a - b; });
                Log.report("网格", "滚动 10 次（" + mode + "）：最长帧间隔 中位 " + gaps[5] + "ms 最大 " + gaps[9] + "ms，掉帧 共 " +
                           g.reduce(function (a, q) { return a + q.drops; }, 0) + "，长任务 共 " + g.reduce(function (a, q) { return a + q.long; }, 0) + "ms");
            }
        }
        requestAnimationFrame(tick);
    }

    /* 换一排（「我」顶上那一排）：这一排的视频流第一次切过来才建、才取。 */
    function setTab(t) {
        var me = cur;
        me.tab = t;
        me.sel = 0;
        me.want = "";
        me.err = "";
        $("gp-grid").innerHTML = "";
        me.cards = [];
        me.on = -1;
        draw();
        var f = feedOf(me);
        if (f && !f.all().length) { more(); }
    }

    /* 回 "left"：「我」顶上那一排最左边再往左、精选最左边那一列再往左 —— app.js 切到左边的标签。回 "right"：精选最右边那一列再往右
     * （精选没有顶上那一排，标签栏也不能选，这是离开它的路）。 */
    function move(dx, dy) {
        var me = cur;
        if (!me) { return ""; }
        var cols = me.geo.cols;
        if (me.kind === "jingxuan" && dx > 0 && (!me.cards.length || me.sel % cols === cols - 1 || me.sel + 1 >= me.cards.length)) { return "right"; }
        if (me.kind === "jingxuan" && dx < 0 && (!me.cards.length || me.sel % cols === 0)) { return "left"; }
        /* 回 "up"：最上面再往上（「我」顶上那一排、没有那一排的页的第一行）—— app.js 把焦点交给顶上的标签栏。 */
        if (me.zone === "tabs") {
            if (dy > 0) { if (me.cards.length) { me.zone = "grid"; measure(focus(true)); } return ""; }
            if (dy < 0) { return "up"; }
            var t = me.tab + dx;
            if (t < 0) { return me.kind === "me" ? "left" : ""; }
            if (t < me.tabs.length) { setTab(t); }
            return "";
        }
        if (!me.cards.length) {
            if (dy < 0 && me.tabs) { me.zone = "tabs"; focus(false); return ""; }
            return dy < 0 ? "up" : "";
        }
        var n = me.cards.length, s = me.sel;
        if (dx) {
            var col = s % cols + dx;
            if (col < 0 || col >= cols || s + dx >= n) { return ""; }
            s += dx;
        } else {
            s += dy * cols;
            if (s < 0) {
                if (me.tabs) { me.zone = "tabs"; focus(false); return ""; }
                return "up";
            }
            if (s >= n) {
                /* 往下到了比这一行短的最后一行：落在最后一张上。已经在最后一行：去取下一页。 */
                if (Math.floor((n - 1) / cols) > Math.floor(me.sel / cols)) { s = n - 1; }
                else { more(); return ""; }
            }
        }
        me.sel = s;
        measure(focus(true));
        return "";
    }

    /* ---------- 三种页 ---------- */

    function author(item) {
        var p = make("author", {
            title: item.author, avatar: item.avatar, playName: "@" + item.author + " 的作品", backName: "TA 的主页",
            makeFeed: function () { return Feed.create("author", {secUid: item.secUid}); },
            empty: function () { return "TA 还没有能在这里放的作品"; },
            foot: function (f, n) { return f.gated() && !Account.loggedIn() ? "没登录只能看到前 " + n + " 个作品 · 在「我」扫码登录后能看全部" : "没有更多了"; }
        });
        p.secUid = item.secUid;
        var t0 = Date.now();
        Bridge.get("/aweme/v1/web/user/profile/other/", {
            sec_user_id: item.secUid, publish_video_strategy_type: "2", personal_center_strategy: "1",
            profile_other_record_enable: "1", land_to: "1"
        }).then(function (j) {
            var u = j.user || {};
            Log.report("作者", "资料 " + (Date.now() - t0) + "ms status_code=" + j.status_code + " @" + Diag.priv(u.nickname) + " 粉丝 " + u.follower_count +
                       " 获赞 " + u.total_favorited + " 作品 " + u.aweme_count);
            if (!u.nickname) { return; }
            header(p, {title: u.nickname, playName: "@" + u.nickname + " 的作品", sign: u.signature || "",
                       stats: "关注 " + count(u.following_count) + "　　粉丝 " + count(u.follower_count) +
                              "　　获赞 " + count(u.total_favorited) + "　　作品 " + count(u.aweme_count),
                       avatar: first(u.avatar_300x300) || first(u.avatar_larger) || undefined});
        }, function (e) { Log.report("作者", "资料取不到：" + e.message); });
        return p;
    }

    /* 「我」：顶上一排观看历史 · 喜欢 · 收藏 · 诊断日志 · 上传诊断日志 · 退出登录。「喜欢」要自己的 sec_uid，资料回来之前那一排写
     * 「正在加载」。诊断日志那两项没有网格，底下那行字是 diag.line(key)，名字是 diag.name()（app.js 给，二维码页用同一套字）。 */
    var ME_TABS = [{key: "history", name: "观看历史"}, {key: "like", name: "喜欢"}, {key: "collect", name: "收藏"},
                   {key: "diag", name: "诊断日志"}, {key: "diagup", name: "上传诊断日志"}, {key: "logout", name: "退出登录"}];
    function me(diag) {
        var p = make("me", {
            title: "我", tabs: ME_TABS, backName: "列表",
            tabName: function (t) { return t.key === "diag" && diag ? diag.name() : t.name; },
            makeFeed: function (k) {
                if (k === "history" || k === "collect") { return Feed.create(k); }
                if (k === "like" && p.secUid) { return Feed.create("like", {secUid: p.secUid}); }
                return null;
            },
            empty: function (k, f) {
                if (k === "logout") { return "按确认键退出登录（要按两次）"; }
                if ((k === "diag" || k === "diagup") && diag) { return diag.line(k); }
                if (k === "like" && !f) { return p.profileErr ? "取不到你的账号信息（" + p.profileErr + "）" : "正在加载…"; }
                return {history: "还没有观看历史", like: "还没有点过赞的视频", collect: "还没有收藏的视频"}[k] || "这里是空的";
            }
        });
        var t0 = Date.now();
        Account.profile().then(function (u) {
            p.secUid = u.sec_uid;
            Log.report("我", "资料 " + (Date.now() - t0) + "ms " + Diag.priv("喜欢 " + u.favoriting_count + " 作品 " + u.aweme_count));   // 账号自己的数字也不出门
            header(p, {title: u.nickname || "我", avatar: first(u.avatar_300x300) || first(u.avatar_thumb) || undefined,
                       stats: "获赞 " + count(u.total_favorited) + "　　关注 " + count(u.following_count) + "　　粉丝 " + count(u.follower_count) +
                              "　　喜欢 " + count(u.favoriting_count)});
            if (cur === p && key(p) === "like") { draw(); more(); }
        }, function (e) {
            p.profileErr = e.message;
            Log.report("我", "资料取不到：" + e.message);
            if (cur === p) { draw(); }
        });
        return p;
    }

    /* 合集（选集）：焦点落在正在看的那一集，卡片左下角写第几集。超过 RANGE 集的分组（顶上一排「1–48 · 49–96 · …」，像抖音
     * App 的选集），打开时在这一集所在的那一组 —— 从第 1 集一页 12 集往后找，462 集的合集取 15 页也只到第 174 集（2026-10-18
     * 设备自测撞上的）。每组一个流，从组的开头取（cursor 就是集数偏移）。 */
    var RANGE = 48;
    function mix(item) {
        var m = item.mix;
        var total = Math.max(m.total || 0, m.ep || 0);
        var tabs = null;
        if (total > RANGE) {
            tabs = [];
            for (var s = 0; s < total; s += RANGE) { tabs.push({key: "r" + s, name: (s + 1) + "–" + Math.min(total, s + RANGE), start: s, limit: RANGE}); }
        }
        var p = make("mix", {
            title: m.name, avatar: m.cover || item.thumb, want: item.id, tabs: tabs,
            stats: (total ? "共 " + total + " 集" : "合集") + (item.author ? "　　@" + item.author : ""), sign: m.desc,
            playName: "合集《" + m.name + "》", backName: "选集",
            makeFeed: function (k) {
                var start = 0;
                for (var i = 0; tabs && i < tabs.length; i++) { if (tabs[i].key === k) { start = tabs[i].start; } }
                return Feed.create("mix", {mixId: m.id, start: start});
            },
            label: function (it) { return it.mix && it.mix.ep ? "第 " + it.mix.ep + " 集" : ""; },
            empty: function () { return "这个合集里没有能在这里放的视频"; }
        });
        if (tabs) { p.tab = Math.min(tabs.length - 1, Math.floor(Math.max(0, m.ep - 1) / RANGE)); }
        p.zone = "grid";
        p.mixId = m.id;
        return p;
    }

    /* 精选：标签自己的页（app.js 每次进这个标签都拿同一页，焦点、列表都还在）。视频流是 app 的那一个（feed.js 的 jingxuan，
     * 带缓存），放的时候上下键接着在里面刷，返回键回到这里。 */
    function jingxuan(getFeed) {
        return make("jingxuan", {
            geo: WIDE, top: 120, playName: "精选", backName: "列表",
            makeFeed: function () { return getFeed(); },
            empty: function () { return "精选暂时没有内容，按确认键重试"; }
        });
    }

    return {
        author: author,
        me: me,
        mix: mix,
        jingxuan: jingxuan,
        /* 新开一页 / 回到这一页（sel：焦点落在第几张，回来时是刚才放的那一条；-1 不动）。 */
        open: render,
        show: function (p, sel) {
            if (sel >= 0) { p.sel = sel; p.zone = "grid"; }
            /* 选集里接着放、放过了这一组的最后一集：回来时换到那一集所在的组，焦点落在它上面。 */
            var lim = limit(p), f = feedOf(p);
            if (lim && sel >= lim && f) {
                var it = f.all()[sel];
                if (it && it.mix && it.mix.ep) { p.tab = Math.min(p.tabs.length - 1, Math.floor((it.mix.ep - 1) / RANGE)); p.want = it.id; p.wantTries = 0; p.sel = 0; }
            }
            render(p);
        },
        close: function () {
            told = probes.filter(function (q) { return q.scrolled; }).length;
            cur = null;
            $("gp-grid").innerHTML = "";
        },
        move: move,
        /* 网格空着（加载失败）时确认键重试。 */
        retry: function () { if (cur && !cur.cards.length) { cur.err = ""; more(); } },
        feed: function () { return cur ? feedOf(cur) : null; },
        zone: function () { return cur ? cur.zone : ""; },
        tabKey: function () { return cur ? key(cur) : ""; },
        toTabs: function () { if (cur && cur.tabs) { cur.zone = "tabs"; focus(false); } },
        /* 顶上那一排和底下那行字照现在的状态重画（诊断日志开关、上传完了）。 */
        refresh: function () { if (cur) { drawTabs(); draw(); } },
        /* 底下那行字临时换一句（退出登录的「再按一次」）。 */
        say: function (msg) { $("gp-foot").textContent = msg; },
        /* 自测 --cold：直接把焦点放到第 i 张。 */
        select: function (i) { if (cur && i < cur.cards.length) { cur.sel = i; cur.zone = "grid"; focus(false); } },
        /* 自测 --grid：轮换做法、读每次翻动的帧。 */
        setMode: function (m) {
            mode = m;
            $("gp-scroll").className = MODES[m][0];
            $("gp-grid").className = MODES[m][1];
        },
        probes: function () { return probes; },
        name: function () { return cur ? cur.title : ""; },
        selected: function () { return cur && cur.zone === "grid" && cur.cards.length ? cur.sel : -1; },
        /* 给自测读的。 */
        state: function () {
            if (!cur) { return null; }
            var imgs = 0;
            for (var i = 0; i < cur.cards.length; i++) { var im = cur.cards[i].querySelector("img"); if (im && im.complete && im.naturalWidth > 0) { imgs++; } }
            return {kind: cur.kind, name: cur.title, cards: cur.cards.length, imgs: imgs, sel: cur.sel, zone: cur.zone, tab: key(cur),
                    stats: $("gp-stats").textContent, avatar: $("gp-avatar").naturalWidth || 0, foot: $("gp-foot").textContent};
        }
    };
})();

files.js/act.js:
/* 点赞、收藏（2026-10-18）：写请求，都经签名桥发。参数照官网前端代码（全新匿名浏览器存下的 bundle）：
 *   点赞  POST /aweme/v1/web/commit/item/digg/   正文 aweme_id、type（1 赞 / 0 取消）、item_type=0；
 *         官网把「status_code=0 但没有 is_digg」也当失败，这里照做
 *   收藏  POST /aweme/v1/web/aweme/collect/      正文 aweme_id、action（1 收藏 / 0 取消）、aweme_type=0
 * **2026-10-18 电视上实测两个都被拒，而且代价很大**：点赞回空正文、再试 HTTP 403；收藏回 status_code=8「用户未登录」——
 * **第一个点赞请求发出去之后，服务器当场作废了电视上的登录**（之前 history/read 是 0，之后是 8，要重新扫码）。官网发这两个时
 * 带 bd-ticket-guard-client-data 这套头，我们没有。所以 SIGNED 是 false 时**一个写请求都不发**（连 --like 自测也发不出去）：
 * 做出 ticket guard 的签名头之前别改它。界面上这两项也跟着不能选（app.js 的 chips）。
 * **服务器说成功了才改界面**（bilibili 那边的规矩：不先改本地状态再假装服务器接受了）。失败原样报 status_code 和 status_msg。
 * 自测构建里不发：它几秒一条地刷，不该替这个账号点赞。只有 --like 那一项自测（赞了马上取消）例外，见 selftest.js。
 */
var Act = (function () {
    "use strict";

    var enc = encodeURIComponent;
    var SIGNED = false;       // 请求带得上 bd-ticket-guard 头了才改成 true —— 不带就发，服务器作废登录（见上）
    var allowSelftest = false;
    function selftest() { return typeof SELFTEST !== "undefined" && !!SELFTEST && !allowSelftest; }

    function post(what, path, body, ok) {
        if (!SIGNED) { return Promise.reject(new Error("还没有 ticket guard 签名头，不发（发了服务器会作废登录）")); }
        if (selftest()) { return Promise.reject(new Error("自测构建不发写请求")); }
        var t0 = Date.now();
        return Bridge.post(path, {}, body).then(function (j) {
            var good = j.status_code === 0 && ok(j);
            Log.report("互动", what + " " + (Date.now() - t0) + "ms status_code=" + j.status_code + (j.status_msg ? " " + j.status_msg : "") +
                       (j.is_digg !== undefined ? " is_digg=" + j.is_digg : "") + " → " + (good ? "成功" : "失败"));
            if (!good) { throw new Error(j.status_msg || "status_code=" + j.status_code); }
            return j;
        }, function (e) {
            Log.report("互动", what + " 请求失败（" + (Date.now() - t0) + "ms）：" + e.message);
            throw e;
        });
    }

    return {
        ready: function () { return SIGNED; },
        like: function (item, on) {
            return post((on ? "点赞 " : "取消点赞 ") + item.id, "/aweme/v1/web/commit/item/digg/",
                        "aweme_id=" + enc(item.id) + "&type=" + (on ? 1 : 0) + "&item_type=0",
                        function (j) { return j.is_digg !== undefined; });
        },
        collect: function (item, on) {
            return post((on ? "收藏 " : "取消收藏 ") + item.id, "/aweme/v1/web/aweme/collect/",
                        "aweme_id=" + enc(item.id) + "&action=" + (on ? 1 : 0) + "&aweme_type=0",
                        function () { return true; });
        },
        /* 自测 --like 用：放开自测构建里的写请求。 */
        allowInSelftest: function () { allowSelftest = true; }
    };
})();

