        var c = clips[k];
        var kind = from === k ? "同一条回开头" : orient(clips[from]) + "→" + orient(c);
        say(label + "：" + orient(c) + "屏 " + c.vw + "x" + c.vh + " · " +
            (fix ? "框已按比例修正 → 应该不变形" + (c.vw < c.vh ? "，居中竖条、两侧黑" : c.vw * 9 < c.vh * 16 ? "，两侧窄黑边" : "，铺满") : "框不修正（全屏）→ 看它变不变形"));
